def rectangles(strings):
    # Handle empty input or empty diagram
    if not strings or not strings[0]:
        return 0

    rows = len(strings)
    cols = len(strings[0])

    # Convert input strings to a list of lists for easier character access.
    # This allows direct indexing like diagram[r][c] without repeated string operations.
    diagram = [list(row) for row in strings]

    # Precompute valid horizontal segments
    # h_segments[r][c1] will store a set of c2 values,
    # for which the segment from (r, c1) to (r, c2) is a valid horizontal line.
    # A valid horizontal line consists of '+' at ends and '-' or '+' in between.
    h_segments = [{} for _ in range(rows)]
    for r in range(rows):
        for c1 in range(cols):
            if diagram[r][c1] == '+':
                for c2 in range(c1 + 1, cols):
                    if diagram[r][c2] == '+':
                        is_valid = True
                        # Check characters between c1 and c2 (exclusive)
                        for c in range(c1 + 1, c2):
                            if diagram[r][c] not in ['-', '+']:
                                is_valid = False
                                break
                        if is_valid:
                            h_segments[r].setdefault(c1, set()).add(c2)

    # Precompute valid vertical segments
    # v_segments[c][r1] will store a set of r2 values,
    # for which the segment from (r1, c) to (r2, c) is a valid vertical line.
    # A valid vertical line consists of '+' at ends and '|' or '+' in between.
    v_segments = [{} for _ in range(cols)]
    for c in range(cols):
        for r1 in range(rows):
            if diagram[r1][c] == '+':
                for r2 in range(r1 + 1, rows):
                    if diagram[r2][c] == '+':
                        is_valid = True
                        # Check characters between r1 and r2 (exclusive)
                        for r in range(r1 + 1, r2):
                            if diagram[r][c] not in ['|', '+']:
                                is_valid = False
                                break
                        if is_valid:
                            v_segments[c].setdefault(r1, set()).add(r2)

    count = 0

    # Iterate through all possible top-left corners (r1, c1)
    for r1 in range(rows):
        for c1 in range(cols):
            # A top-left corner must be a '+'
            if diagram[r1][c1] != '+':
                continue

            # For each potential top-left corner (r1, c1):
            # 1. Find all possible top-right corners (r1, c2) using precomputed horizontal segments.
            #    `h_segments[r1].get(c1, set())` provides a set of valid `c2`s for the top line.
            for c2 in h_segments[r1].get(c1, set()): 
                # 2. Find all possible bottom-left corners (r2, c1) using precomputed vertical segments.
                #    `v_segments[c1].get(r1, set())` provides a set of valid `r2`s for the left line.
                for r2 in v_segments[c1].get(r1, set()): 
                    # At this point, we have identified three corners: (r1, c1), (r1, c2), (r2, c1)
                    # and confirmed the validity of the top and left lines connecting them.

                    # 3. Check if the fourth corner (r2, c2) exists and is a '+'
                    if diagram[r2][c2] == '+':
                        # 4. Check if the bottom line segment from (r2, c1) to (r2, c2) is valid.
                        #    We use `h_segments[r2].get(c1, set())` to check if `c2` is a valid endpoint for `c1` on row `r2`.
                        if c2 in h_segments[r2].get(c1, set()):
                            # 5. Check if the right line segment from (r1, c2) to (r2, c2) is valid.
                            #    We use `v_segments[c2].get(r1, set())` to check if `r2` is a valid endpoint for `r1` on column `c2`.
                            if r2 in v_segments[c2].get(r1, set()):
                                # All conditions met, we found a valid rectangle
                                count += 1
    return count

